/**
 * Shared HashiCorp Vault helpers for external secrets, used by bruno-electron and bruno-cli.
 *
 * The low-level client lives in ./client (createVaultClient). These higher-level helpers are
 * environment-agnostic: proxy/TLS is the only environment-specific concern, so callers pass a
 * `resolveAgents(url)` that returns `{ httpAgent, httpsAgent }` for a request URL (electron
 * resolves from its preferences, the CLI from its run options). Vault Cloud calls go out via
 * axios directly; Vault Server calls go through a created client whose agents are baked in.
 */

import axios from 'axios';
import createVaultClient, { VAULT_REQUEST_TIMEOUT_MS } from './client';
import { buildResolveAgents } from '../resolve-agents';
import type { ResolveAgents, SecretManagerNetworkConfig } from '../resolve-agents';

export interface VaultPathResult {
  path: string;
  data?: any;
  error?: any;
}

export interface NormalizedVaultError {
  message: string;
  type: 'ssl_certificate' | 'network' | 'authentication' | 'vault_api' | 'http' | 'unknown';
  code?: string;
  originalError: any;
  context: Record<string, any>;
}

// Normalize a Vault/axios error into a categorized shape for logging and surfacing. Returns the
// original error information without inventing custom messages.
export const handleVaultError = (error: any, context: Record<string, any> = {}): NormalizedVaultError => {
  let errorMessage = error?.message || 'An unexpected error occurred';
  const errorCode = error?.code;
  let errorType: NormalizedVaultError['type'] = 'unknown';

  if (
    errorCode?.includes('CERT')
    || errorCode?.includes('SSL')
    || errorCode?.includes('TLS')
    || errorCode === 'UNABLE_TO_VERIFY_LEAF_SIGNATURE'
    || error?.message?.toLowerCase().includes('certificate')
    || error?.message?.toLowerCase().includes('ssl')
    || error?.message?.toLowerCase().includes('tls')
  ) {
    errorType = 'ssl_certificate';
  } else if (
    errorCode === 'ETIMEDOUT'
    || errorCode === 'ECONNRESET'
    || errorCode === 'ECONNREFUSED'
    || errorCode === 'ENOTFOUND'
    || errorCode === 'EAI_AGAIN'
  ) {
    errorType = 'network';
  } else if (error?.response?.status === 401 || error?.response?.status === 403) {
    errorType = 'authentication';
  } else if (error?.response?.body || error?.response?.data) {
    errorType = 'vault_api';
    const vaultError = error?.response?.body || error?.response?.data;
    if (typeof vaultError === 'object' && vaultError?.errors) {
      errorMessage = vaultError.errors.join(', ');
    } else if (typeof vaultError === 'string') {
      errorMessage = vaultError;
    }
  } else if (error?.response?.status) {
    errorType = 'http';
    errorMessage = error?.response?.statusText || `HTTP ${error.response.status}`;
  }

  return {
    message: errorMessage,
    type: errorType,
    code: errorCode,
    originalError: {
      message: error?.message,
      code: error?.code,
      response: error?.response
        ? {
            status: error.response.status,
            statusText: error.response.statusText,
            body: error.response.body,
            data: error.response.data
          }
        : undefined,
      stack: error?.stack
    },
    context
  };
};

// In-memory store of Vault tokens keyed by endpoint, used to reuse and auto-renew LDAP tokens
// within a process. Clears a stored token when the auth data it was issued for changes.
export const tokenStorage = {
  vault: {} as Record<string, { token: string; metadata: any; createdAt: number }>,
  storeToken(endpoint: string, token: string, metadata: any = {}) {
    this.vault[endpoint] = { token, metadata, createdAt: new Date().getTime() };
  },
  getTokenInfo(endpoint: string) {
    return this.vault[endpoint];
  },
  updateToken(endpoint: string, token: string, metadata: any = {}) {
    if (this.vault[endpoint]) {
      this.vault[endpoint].token = token;
      this.vault[endpoint].metadata = { ...this.vault[endpoint].metadata, ...metadata };
    } else {
      this.storeToken(endpoint, token, metadata);
    }
  },
  clearToken(endpoint: string) {
    delete this.vault[endpoint];
  },
  checkAndClearIfChanged(endpoint: string, currentAuthData: any) {
    const stored = this.getTokenInfo(endpoint);
    if (stored?.metadata?.authData) {
      const isEqual = require('lodash/isEqual');
      if (!isEqual(stored.metadata.authData, currentAuthData)) {
        this.clearToken(endpoint);
      }
    }
  }
};

// Read each path from a Vault server using a created client. Errors are returned per-path
// (normalized) so one failure doesn't abort the rest.
export const fetchVaultServerSecrets = async ({ paths, vault }: { paths: string[]; vault: any }): Promise<VaultPathResult[]> => {
  return Promise.all(
    (paths || []).map(async (path): Promise<VaultPathResult> => {
      try {
        const res = await vault.read(path);
        const data = res?.data?.data || res?.data;
        return { path, data };
      } catch (e: any) {
        const error = handleVaultError(e, { path, operation: 'read' });
        return { path, error };
      }
    })
  );
};

export const getVaultServerApproleToken = async ({ vault, options }: { vault: any; options: any }): Promise<string> => {
  const { role, roleId, secretId, mountPath } = options || {};
  try {
    const res = await vault.approleLogin({ role, role_id: roleId, secret_id: secretId, mount_point: mountPath });
    return res?.auth?.client_token;
  } catch (e: any) {
    throw new Error(handleVaultError(e, { operation: 'getVaultServerApproleToken', role: options?.role }).message);
  }
};

// Authenticate against Vault's LDAP backend, caching the issued token for reuse/renewal.
export const getVaultServerLdapToken = async ({ vault, options }: { vault: any; options: any }): Promise<string> => {
  const { username, password } = options || {};
  const currentAuthData = { username, password };
  tokenStorage.checkAndClearIfChanged(vault.endpoint, currentAuthData);

  try {
    const response = await vault.write(`auth/ldap/login/${username}`, { password });
    const token = response?.auth?.client_token;
    if (!token) {
      throw new Error('Failed to obtain token from LDAP authentication');
    }
    tokenStorage.storeToken(vault.endpoint, token, {
      renewable: response.auth.renewable,
      ttl: response.auth.lease_duration,
      policies: response.auth.policies,
      metadata: response.auth.metadata,
      authData: currentAuthData
    });
    return token;
  } catch (error: any) {
    throw new Error(handleVaultError(error, { operation: 'getVaultServerLdapToken', username }).message);
  }
};

// Decide whether a renewable token is close enough to expiry to warrant renewal.
export const shouldRenewToken = async ({ vault, tokenInfo, autoRenew }: { vault: any; tokenInfo: any; autoRenew: boolean }): Promise<boolean> => {
  if (!autoRenew || !tokenInfo || !tokenInfo.metadata.renewable) {
    return false;
  }
  const currentToken = vault.token;
  vault.token = tokenInfo.token;
  try {
    const lookup = await vault.tokenLookupSelf();
    const ttl = lookup.data?.ttl || 0;
    const creationTtl = lookup.data?.creation_ttl || 0;
    return ttl > 0 && (ttl < 300 || (creationTtl > 0 && ttl < creationTtl * 0.25));
  } catch (error) {
    return true;
  } finally {
    vault.token = currentToken;
  }
};

export const renewVaultToken = async ({ vault, token }: { vault: any; token: string }): Promise<string> => {
  const currentToken = vault.token;
  vault.token = token;
  try {
    const result = await vault.tokenRenewSelf();
    tokenStorage.updateToken(vault.endpoint, token, {
      renewable: result.auth.renewable,
      ttl: result.auth.lease_duration
    });
    return token;
  } catch (error: any) {
    throw new Error('Failed to renew token: ' + handleVaultError(error, { operation: 'renewVaultToken' }).message);
  } finally {
    vault.token = currentToken;
  }
};

export const configureVaultInstance = (vault: any, config: any) => {
  vault.endpoint = config.vaultServerConfig.url;
  if (config.vaultServerConfig.namespace?.length) {
    vault.namespace = config.vaultServerConfig.namespace;
  }
  return vault;
};

// Resolve an LDAP-authenticated token onto the client, reusing/renewing a cached token when
// possible and falling back to a fresh login otherwise. Honors the `autoRenew` option.
export const handleLdapAuthentication = async (vault: any, config: any): Promise<string> => {
  const currentAuthData = {
    username: config.vaultServerConfig.auth.ldap.username,
    password: config.vaultServerConfig.auth.ldap.password
  };
  tokenStorage.checkAndClearIfChanged(vault.endpoint, currentAuthData);

  const tokenInfo = tokenStorage.getTokenInfo(vault.endpoint);
  let accessToken: string;

  if (tokenInfo && tokenInfo.token) {
    vault.token = tokenInfo.token;
    try {
      const autoRenew = !!config.vaultServerConfig.auth.ldap.autoRenew;
      const shouldRenew = await shouldRenewToken({ vault, tokenInfo, autoRenew });

      if (shouldRenew) {
        try {
          accessToken = await renewVaultToken({ vault, token: tokenInfo.token });
        } catch (error) {
          accessToken = await getVaultServerLdapToken({ vault, options: config.vaultServerConfig.auth.ldap });
        }
      } else if (!autoRenew) {
        try {
          await vault.tokenLookupSelf();
          accessToken = tokenInfo.token;
        } catch (tokenError) {
          throw new Error('LDAP token has expired. Auto-renew is disabled. Please re-authenticate.');
        }
      } else {
        accessToken = tokenInfo.token;
      }
    } catch (error: any) {
      if (error.message && error.message.includes('Auto-renew is disabled')) {
        throw error;
      }
      accessToken = await getVaultServerLdapToken({ vault, options: config.vaultServerConfig.auth.ldap });
    }
  } else {
    accessToken = await getVaultServerLdapToken({ vault, options: config.vaultServerConfig.auth.ldap });
  }

  vault.token = accessToken;
  return accessToken;
};

export const getVaultCloudToken = async ({ options, resolveAgents }: { options: any; resolveAgents: ResolveAgents }): Promise<string> => {
  const { tokenEndpoint, clientId, clientSecret } = options || {};
  const { httpAgent, httpsAgent } = await resolveAgents(tokenEndpoint);
  try {
    const response = await axios.post(
      tokenEndpoint,
      {
        grant_type: 'client_credentials',
        client_id: clientId,
        client_secret: clientSecret,
        audience: 'https://api.hashicorp.cloud'
      },
      {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        httpAgent,
        httpsAgent,
        proxy: false,
        timeout: VAULT_REQUEST_TIMEOUT_MS
      }
    );
    return response?.data?.access_token;
  } catch (error: any) {
    throw new Error(handleVaultError(error, { operation: 'getVaultCloudToken' }).message);
  }
};

// Fetch the secrets of an HCP Vault Cloud app (the first path segment is the app name).
export const getVaultCloudSecrets = async ({
  options,
  accessToken,
  path,
  resolveAgents
}: {
  options: any;
  accessToken: string;
  path: string;
  resolveAgents: ResolveAgents;
}): Promise<VaultPathResult> => {
  const { secretsEndpoint, organizationId, projectId } = options || {};
  if (!organizationId || !projectId) {
    return { path, data: {} };
  }
  const appName = encodeURIComponent(path.split('/')?.[0] || '');
  const requestUrl = `${secretsEndpoint}/organizations/${organizationId}/projects/${projectId}/apps/${appName}/open`;
  const { httpAgent, httpsAgent } = await resolveAgents(requestUrl);
  try {
    const data: Record<string, any> = {};
    // HCP Vault Secrets paginates the open-app response; follow pagination.next_page_token until it
    // is empty, otherwise apps with more than one page of secrets silently drop the tail. Track seen
    // tokens so a non-advancing/repeating token from a misbehaving endpoint can't loop forever.
    const seenPageTokens = new Set<string>();
    let nextPageToken: string | undefined;
    do {
      const response = await axios.get(requestUrl, {
        headers: { Authorization: `Bearer ${accessToken}` },
        params: nextPageToken ? { 'pagination.next_page_token': nextPageToken } : undefined,
        httpAgent,
        httpsAgent,
        proxy: false,
        timeout: VAULT_REQUEST_TIMEOUT_MS
      });
      const body = response.data;
      if (!body || typeof body !== 'object') {
        throw new Error('Unexpected response from HCP Vault Secrets (missing body)');
      }
      for (const secret of body.secrets || []) {
        if (!secret?.name) continue;
        data[secret.name] = secret?.version?.value;
      }
      nextPageToken = body.pagination?.next_page_token || undefined;
      if (nextPageToken && seenPageTokens.has(nextPageToken)) {
        break;
      }
      if (nextPageToken) {
        seenPageTokens.add(nextPageToken);
      }
    } while (nextPageToken);
    return { path, data };
  } catch (error: any) {
    return { path, error: handleVaultError(error, { operation: 'getVaultCloudSecrets', path }) };
  }
};

// Validate Vault connectivity/credentials without fetching secrets. Returns the token-lookup
// result (token/ldap) or the resolved access token (app_role).
export const vaultWhoami = async ({
  config,
  networkConfig,
  debug
}: {
  config: any;
  networkConfig?: SecretManagerNetworkConfig;
  debug?: (...args: any[]) => void;
}): Promise<any> => {
  if (!config?.type) return undefined;
  const resolveAgents = buildResolveAgents(networkConfig);

  if (config?.type === 'hashicorp-vault-server') {
    const requestOptions = await resolveAgents(config?.vaultServerConfig?.url);
    const vault = createVaultClient({ apiVersion: 'v1', requestOptions, debug });
    const method = config?.vaultServerConfig?.auth?.method;

    if (method === 'token') {
      configureVaultInstance(vault, config);
      vault.token = config?.vaultServerConfig?.auth?.token;
      return vault.tokenLookupSelf();
    }
    if (method === 'app_role') {
      configureVaultInstance(vault, config);
      return getVaultServerApproleToken({ vault, options: config?.vaultServerConfig?.auth?.appRole });
    }
    if (method === 'ldap') {
      configureVaultInstance(vault, config);
      await handleLdapAuthentication(vault, config);
      return vault.tokenLookupSelf();
    }
    return undefined;
  }

  if (config?.type === 'hashicorp-vault-cloud') {
    if (config?.vaultCloudConfig?.auth?.method === 'client_credentials' && config?.vaultCloudConfig?.auth?.clientCredentials) {
      return getVaultCloudToken({ options: config?.vaultCloudConfig?.auth?.clientCredentials, resolveAgents });
    }
    return undefined;
  }

  return undefined;
};

// Fetch all configured secrets for a Vault provider (server token/app_role/ldap, or cloud).
// Builds the client/token internally; proxy/TLS comes from `resolveAgents`.
export const fetchHashicorpVaultSecrets = async ({
  config,
  paths,
  networkConfig,
  debug
}: {
  config: any;
  paths: string[];
  networkConfig?: SecretManagerNetworkConfig;
  debug?: (...args: any[]) => void;
}): Promise<VaultPathResult[] | undefined> => {
  const resolveAgents = buildResolveAgents(networkConfig);
  if (config?.type === 'hashicorp-vault-server') {
    const requestOptions = await resolveAgents(config?.vaultServerConfig?.url);
    const vault = createVaultClient({ apiVersion: 'v1', requestOptions, debug });
    const method = config?.vaultServerConfig?.auth?.method;
    configureVaultInstance(vault, config);

    if (method === 'token') {
      vault.token = config?.vaultServerConfig?.auth?.token;
    } else if (method === 'app_role') {
      vault.token = await getVaultServerApproleToken({ vault, options: config?.vaultServerConfig?.auth?.appRole });
    } else if (method === 'ldap') {
      await handleLdapAuthentication(vault, config);
    } else {
      return undefined;
    }
    return fetchVaultServerSecrets({ vault, paths });
  }

  if (config?.type === 'hashicorp-vault-cloud') {
    if (
      config?.vaultCloudConfig?.auth?.method === 'client_credentials'
      && config?.vaultCloudConfig?.auth?.clientCredentials
      && config?.vaultCloudConfig?.project
    ) {
      const accessToken = await getVaultCloudToken({ options: config?.vaultCloudConfig?.auth?.clientCredentials, resolveAgents });
      return Promise.all(
        (paths || []).map((path) =>
          getVaultCloudSecrets({
            options: { ...config?.vaultCloudConfig?.auth?.clientCredentials, ...config?.vaultCloudConfig?.project },
            accessToken,
            path,
            resolveAgents
          })
        )
      );
    }
    return undefined;
  }

  return undefined;
};

export { default as createVaultClient, VaultError } from './client';
export type { VaultClient, VaultConfig, VaultRequestOptions } from './client';
